5 -70.06612 12.54697     1     5  Aruba      &lt;NA&gt;
6 -70.05088 12.59707     1     6  Aruba      &lt;NA&gt;

ggplot(world_data, aes(x = long, y = lat, group = group)) +
  geom_polygon(fill = "lightgray", color = "white") +
  theme_minimal()







